#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Interactive SSH setup. Only the remote host receives a persistent credential.
set +x +v
umask 077
ulimit -c 0
ENV_FILE=/dev/null
unset HOSTINGER_SETUP_TOKEN
HOSTINGER_SETUP_TOKEN=''
trap 'unset HOSTINGER_SETUP_TOKEN' EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
[[ -t 0 && -t 1 ]] || { printf '%sRun this script in an interactive local terminal.%s\n' "$RED" "$RESET" >&2; exit 2; }
command -v ssh >/dev/null
command -v python3 >/dev/null
TOTAL_STAGES=3

[[ $# -eq 1 && $1 =~ ^[A-Za-z0-9][A-Za-z0-9._@:-]*$ ]] || {
  say "Usage: bash tools/setup-hostinger-broker.sh <SSH-destination>"
  exit 2
}
HOSTINGER_SETUP_DESTINATION=$1
HOSTINGER_SETUP_TOOLS=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
# Send only public source as a command argument. The token travels on SSH stdin.
HOSTINGER_SETUP_REMOTE_QUOTED=$(python3 -I "$HOSTINGER_SETUP_TOOLS/setup-hostinger-broker.py" bundle --quote)

remote_setup() {
  local mode="$1" fingerprint="${2:-}"
  [[ $mode == preflight || $mode == inspect || $mode == apply ]]
  [[ -z $fingerprint || $fingerprint =~ ^[a-f0-9]{64}$ ]]
  printf '%s' "$HOSTINGER_SETUP_TOKEN" |
    ssh -T -o BatchMode=yes -o StrictHostKeyChecking=yes -o ConnectTimeout=10 \
      -o ServerAliveInterval=15 -o ServerAliveCountMax=3 "$HOSTINGER_SETUP_DESTINATION" \
      "/usr/bin/python3 -I -c $HOSTINGER_SETUP_REMOTE_QUOTED bridge $mode $fingerprint"
}

# This wizard does not use the template's saved-value helpers or banner: token
# entry is deliberately fresh on every run and no local values are remembered.
say "Connect Governor through the key manager · $TOTAL_STAGES stages"
note "No token is saved locally. Cancelling means entering it again next time."
pause "Ready to start?"
remote_setup preflight
stage "Create a token in the account that owns the VPS"
open_url "https://hpanel.hostinger.com/"
step "Sign in to the Hostinger account that owns $HOSTINGER_SETUP_DESTINATION."
step "Dev tools > API > API tokens > New token."
step "Name it governor-cpu-metrics, choose an expiration date, then Generate."
step "Copy the token before leaving the page. Set a reminder to rotate it before expiry."
warn "This token can manage your Hostinger account. Never paste it into chat or a command."
pause "Press Enter when the token is ready."

stage "Enter the token privately and verify the VPS"
ask_secret HOSTINGER_SETUP_TOKEN "Paste the token here; input is hidden:"
[[ -n $HOSTINGER_SETUP_TOKEN ]] || { say "No token entered. Nothing changed."; exit 1; }
say "Checking VM details and CPU metrics over HTTPS. No credential is saved yet."
HOSTINGER_SETUP_RESULT=$(remote_setup inspect)
HOSTINGER_SETUP_FINGERPRINT=$(printf '%s' "$HOSTINGER_SETUP_RESULT" |
  python3 -I -c 'import json,sys; print(json.load(sys.stdin)["config_hash"])')
printf '%s' "$HOSTINGER_SETUP_RESULT" |
  python3 -I -c 'import json,sys; r=json.load(sys.stdin); print("  Verified VM",r["vm_id"],"with",r["cpus"],"vCPUs and",r["cpu_samples"],"CPU readings.")'

stage "Install the restricted broker and verify Governor"
say "The encrypted token will be root-only at /etc/key-manager/hostinger/token.cred."
say "Only the isolated key-manager-hostinger worker will receive the token."
say "Governor can request VM details and CPU metrics for this VPS only, never the token."
say "The worker has no home-directory access and uses its own Unix identity."
say "The script preserves other settings, backs up the config and restarts only Governor."
say "An installer-managed raw token is retired to an encrypted, root-only backup."
note "A brief fallback CPU cap applies during the restart. Existing jobs are not restarted."
note "Root can still recover the token. This does not protect against a compromised VPS administrator."
if ! confirm "Install the restricted broker and restart Governor on $HOSTINGER_SETUP_DESTINATION"; then
  unset HOSTINGER_SETUP_TOKEN
  say "Cancelled. No credential or Governor configuration was saved."
  exit 0
fi
HOSTINGER_SETUP_RESULT=$(remote_setup apply "$HOSTINGER_SETUP_FINGERPRINT")
unset HOSTINGER_SETUP_TOKEN
printf '%s' "$HOSTINGER_SETUP_RESULT" |
  python3 -I -c 'import json,sys; r=json.load(sys.stdin); print("  API configured for VM",r["vm_id"]); print("  Operation-only broker verified. Estimated credits:",r["balance"]); print("  Accepting work:",r["accepting"]); print("  Protected config backup:",r["backup"])'
say "Hostinger history will appear after the next scheduled check, within about 30 minutes."
note "A failed setup may leave a locked worker account and sanitized metric cache. No token is stored there."
say "Clear your clipboard now. Nothing was stored locally or sent to GitHub."
finish

